SELECT dept_name, CASE WHEN dept_name IN ('Finance', 'Sales') THEN 'core' ELSE 'other' END AS dept_name_group, SUM(budget) AS total_budget, SUM(CASE WHEN location = 'Singapore' THEN 1 ELSE 0 END) AS singapore_count FROM departments WHERE location != 'Chiang Mai' AND location IN ('New York', 'Berlin') GROUP BY dept_name, CASE WHEN dept_name IN ('Finance', 'Sales') THEN 'core' ELSE 'other' END
